function validateScheduleTimezone(e){let t=e.trim();if(t.length===0||t.length>50||/^[+-]/.test(t))throw Error(`Schedule timezone must be a valid IANA timezone.`);try{return new Intl.DateTimeFormat(`en-US`,{timeZone:t}).resolvedOptions().timeZone}catch{throw Error(`Invalid IANA timezone: ${t}`)}}export{validateScheduleTimezone};